contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seedMarketDrugs) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(seedMarketDrugs > 0);

        // Seed the market to initialize the contract
        c.seedMarket{value: 0}(seedMarketDrugs); if (__ESBMC_reverted()) return;

        // Ensure caller currently has zero kilos (fresh test contract should have zero)
        uint256 kilosBefore = c.getMyKilo(); if (__ESBMC_reverted()) return;
        require(kilosBefore == 0);

        bool reverted;
        c.getFreeKilo(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 kilosAfter = c.getMyKilo(); if (__ESBMC_reverted()) return;
        uint256 starting = c.STARTING_KILOS(); if (__ESBMC_reverted()) return;

        // If seedMarket initialized and caller had zero kilos, getFreeKilo must not revert and must set kilos to STARTING_KILOS
        assert(!reverted && kilosAfter == starting);
    }

    receive() external payable {}
}

