// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedMarketDrugs) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(seedMarketDrugs > 0);
        try c.seedMarket{value: 0}(seedMarketDrugs) {} catch { return; }
        uint256 kilosBefore;
        try c.getMyKilo() returns (uint256 __r) { kilosBefore = __r; } catch { return; }
        vm.assume(kilosBefore == 0);
        bool reverted;
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 kilosAfter;
        try c.getMyKilo() returns (uint256 __r) { kilosAfter = __r; } catch { return; }
        uint256 starting;
        try c.STARTING_KILOS() returns (uint256 __r) { starting = __r; } catch { return; }
        assertTrue(!reverted && kilosAfter == starting);
    }

    function testFuzz_run(uint256 seedMarketDrugs) public {
        _run(seedMarketDrugs);
    }

    receive() external payable {}
}
